/* One order row per line of a payment. The Stripe webhook looks an order up by orders.stripe_session_id before it writes one, so a second delivery of the same payment writes nothing, but two deliveries at the same moment both find nothing and both write, and nothing in the database refused the second. A plain unique index on stripe_session_id would be wrong: a basket (lib/checkout/fulfil-cart-item.ts) and a physical order (lib/physical/checkout-server.ts) write one row per line, all with the same session. What tells those lines apart is receipt_token: a basket's line has cartReceiptToken(session, its place in the basket), and a single product's order has the token the checkout put in the session's metadata, the same on every delivery. So the key is (stripe_session_id, receipt_token), only where both are set: the second insert of a line fails with 23505, and the webhook reads the first one back. Made only when no line is already written twice; otherwise it skips itself with a notice giving the count and the query to see them, and changes nothing. Changes no row. Nothing where there is no orders table. Needs nothing else. LOCK: a plain CREATE UNIQUE INDEX stops inserts, updates and deletes on orders while it builds (seconds on a large table), and the editor holds that until the paste ends. Until it runs, orders are written as before. Safe to run again. */
DO $do$ DECLARE n bigint; BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'part 190: there is no orders table, nothing to do.'; RETURN; END IF; IF to_regclass('public.orders_stripe_session_line_key') IS NOT NULL THEN RETURN; END IF; SELECT count(*) INTO n FROM (SELECT 1 FROM public.orders WHERE stripe_session_id IS NOT NULL AND receipt_token IS NOT NULL GROUP BY stripe_session_id, receipt_token HAVING count(*) > 1) d; IF n > 0 THEN RAISE NOTICE 'part 190 skipped: % payment lines are written more than once, so the one row per payment line index was not made. See them with: select stripe_session_id, receipt_token, count(*), array_agg(id order by created_at) from public.orders where stripe_session_id is not null and receipt_token is not null group by 1, 2 having count(*) > 1;', n; RETURN; END IF; CREATE UNIQUE INDEX IF NOT EXISTS orders_stripe_session_line_key ON public.orders (stripe_session_id, receipt_token) WHERE stripe_session_id IS NOT NULL AND receipt_token IS NOT NULL; END $do$;
notify pgrst, 'reload schema';
